def detect_domain(text: str) -> str:
    """Pick the best-matching domain for a consultation text."""
    text = text or ""
    best = "generic"
    best_score = 2  # require at least two keyword points to leave generic
    for key, domain in DOMAINS.items():
        if key == "generic":
            continue
        score = sum(weight for word, weight in domain["keywords"] if word in text)
        if score > best_score:
            best, best_score = key, score
    return best


def domain_questions(domain: str) -> list[dict]:
    return list(DOMAINS.get(domain, DOMAINS["generic"])["questions"])


def domain_issues(domain: str) -> list[tuple[str, str]]:
    return list(DOMAINS.get(domain, DOMAINS["generic"])["issues"])


def domain_evidence(domain: str) -> list[str]:
    return list(DOMAINS.get(domain, DOMAINS["generic"])["evidence"])


def domain_risks(domain: str) -> list[str]:
    return list(DOMAINS.get(domain, DOMAINS["generic"])["risks"])


def domain_label(domain: str) -> str:
    return DOMAINS.get(domain, DOMAINS["generic"])["label"]
